<?php
declare(strict_types=1);
if(!defined('ANKH_PORTAL_VIEW') || empty($customer) || !empty($isDemo)){http_response_code(404);exit;}
$catalogueError=false;
try{$catalogueProducts=ankhCatalogueProducts($admin,(int)$customer['id']);}
catch(Throwable $e){error_log('ANKH customer catalogue: '.$e->getMessage());$catalogueProducts=[];$catalogueError=true;}
$catalogueSearch=is_string($_GET['search']??null)?substr(trim($_GET['search']),0,80):'';
$catalogueCategory=is_string($_GET['category']??null)?$_GET['category']:'all';
if(!in_array($catalogueCategory,['all','Research materials','Storage','Stationery'],true))$catalogueCategory='all';
$catalogueVisible=array_filter($catalogueProducts,static fn(array $p):bool=>($catalogueCategory==='all'||$p['category']===$catalogueCategory)&&($catalogueSearch===''||stripos($p['name'].' '.$p['description'],$catalogueSearch)!==false));
?>
<section class="pc-page-heading"><span class="pc-eyebrow">YOUR ANKH RESEARCH CATALOGUE</span><h1>Our catalogue<span class="pc-dot">.</span></h1><p>Current product information, prices and availability from ANKH.</p></section>
<div class="pcd-notice" role="note"><?=pcIcon('shield')?><div><strong>Laboratory research only · 18+</strong><span>For laboratory research, in-vitro testing and academic evaluation only. Not for human or animal consumption. Not intended to diagnose, treat, cure or prevent disease.</span></div></div>
<?php if($staff):?><div class="pcd-notice" role="note"><?=pcIcon('shield')?><div><strong>Connected to Admin</strong><span>Only products ticked “Visible on customer's dashboard” in Admin → Products appear here. This screen reads existing records; it does not change orders or stock.</span></div></div><?php endif;?>
<div class="pc-panel pc-filter-panel"><form class="pc-filter-form" method="get" action="<?=$staff?'./preview-live.php':'./'?>"><?php if($staff):?><input type="hidden" name="customer_id" value="<?=$customerId?>"><?php endif;?><input type="hidden" name="tab" value="catalogue"><label for="live-catalogue-search"><?=pcIcon('search')?><span class="sr-only">Search the catalogue</span></label><input type="search" id="live-catalogue-search" name="search" maxlength="80" value="<?=portalEscape($catalogueSearch)?>" placeholder="Find a product"><select name="category" aria-label="Product category"><?php foreach(['all'=>'All categories','Research materials'=>'Research materials','Storage'=>'Storage','Stationery'=>'Stationery'] as $key=>$label):?><option value="<?=$key?>" <?=$catalogueCategory===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select><button type="submit">Search</button></form></div>
<?php if($catalogueError):?><div class="pc-panel pc-empty" role="alert"><h2>Catalogue temporarily unavailable</h2><p>Please try again later or contact ANKH.</p></div>
<?php elseif(!$catalogueVisible):?><div class="pc-panel pc-empty"><h2><?=$catalogueSearch!==''||$catalogueCategory!=='all'?'No matching products':'No products published yet'?></h2><p><?=$catalogueSearch!==''||$catalogueCategory!=='all'?'Try a different search or category.':'Products will appear here when ANKH publishes them.'?></p><?php if($catalogueSearch!==''||$catalogueCategory!=='all'):?><a href="<?=portalEscape(pcHref('catalogue',$staff,$customerId))?>">Clear filters</a><?php endif;?></div>
<?php else:?><div class="pcd-product-grid"><?php foreach($catalogueVisible as $catalogueProduct):?><article class="pcd-product"><div class="pcd-product-art"><span class="pcd-live-symbol" aria-hidden="true"><?=pcIcon('catalogue')?></span><span class="pcd-art-caption">ANKH / RESEARCH</span><span class="pcd-stock"><?=$catalogueProduct['available_qty']===null?'Availability to confirm':($catalogueProduct['available_qty']>0?'Available · '.$catalogueProduct['available_qty']:'Currently unavailable')?></span></div><div class="pcd-product-copy"><span class="pc-eyebrow"><?=portalEscape($catalogueProduct['category'])?></span><h2><?=portalEscape($catalogueProduct['name'])?></h2><?php if($catalogueProduct['description']!==''):?><p><?=nl2br(portalEscape($catalogueProduct['description']))?></p><?php endif;?><div class="pcd-price"><strong><?=portalEscape(portalMoney($catalogueProduct['price']))?></strong><small><?=$catalogueProduct['pricing']==='family_friends'?'Your Family & Friends price':($catalogueProduct['pricing']==='free'?'Your account price':'Retail price')?></small></div><a class="pc-outline-button" href="mailto:info@ankhpeptides.com?subject=<?=rawurlencode('Research catalogue enquiry: '.$catalogueProduct['name'])?>"><?=pcIcon('mail')?> Enquire about this product</a></div></article><?php endforeach;?></div><p class="pc-footnote">Availability reflects current Admin stock records and may change. Ordering through this catalogue is not enabled yet.</p><?php endif;?>
